type UpdateOrganizationPlanParams struct {
	Plan  string
	OrgID uuid.UUID
}

func (q *Queries) UpdateOrganizationPlan(ctx context.Context, arg UpdateOrganizationPlanParams) (Organization, error) {
	row := q.db.QueryRow(ctx, updateOrganizationPlan, arg.Plan, arg.OrgID)
	var i Organization
	err := row.Scan(
		&i.OrgID,
		&i.Name,
		&i.TimeZone,
		&i.DisplayName,
		&i.Domain,
		&i.Plan,
		&i.OwnerUserID,
		&i.IdempotencyKey,
		&i.DomainVerifiedAt,
		&i.PendingDomain,
		&i.DomainVerificationToken,
		&i.Status,
		&i.SuspendedAt,
		&i.SuspensionReason,
		&i.ClosingAt,
		&i.PurgeAfter,
		&i.CloseReason,
		&i.ClosedByUserID,
		&i.ReopenTokenHash,
		&i.AuditMonths,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.LastModifiedBy,
		&i.LastModifiedAt,
	)
	return i, err
}
